-- =====================================================================
-- AI LAB HUB — міграція 2026-10-17: запасний пошук Елі без AI (app/eli-search.php)
--
--   search_intents — основа слова → категорія / підкатегорія з вагою (вивч → Освіта, відео → Відеомонтаж…).
--     category_id / subcategory_id беруться за slug (на хостингу id інші); рядок додається, лише якщо
--     такої пари ще немає. Джерело списку — tools/eli-intents.php (php tools/eli-intents.php list).
--   categories.search_only_on_match — чутливий розділ: його продукти потрапляють у запасну добірку
--     лише коли запит прямо про нього. Початково 1: «Релігія», «Здоров'я та краса».
--     Змінюється лише при першому додаванні колонки (потім — вручну).
--
-- Лише CREATE TABLE IF NOT EXISTS / безпечні ALTER (information_schema + PREPARE) / INSERT … WHERE NOT EXISTS.
-- Жодних DROP / TRUNCATE. Повторний запуск безпечний.
-- Застосування: phpMyAdmin → БД → «Импорт» → цей файл → Вперёд.
-- =====================================================================

SET NAMES utf8mb4;
SET @db := DATABASE();

CREATE TABLE IF NOT EXISTS search_intents (
    id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
    term_stem      VARCHAR(40) NOT NULL,
    category_id    INT UNSIGNED NULL,
    subcategory_id INT UNSIGNED NULL,
    weight         DECIMAL(4, 2) NOT NULL DEFAULT 1.00,
    created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_search_intents_term (term_stem)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

SET @had_flag := (SELECT COUNT(*) FROM information_schema.COLUMNS
                   WHERE TABLE_SCHEMA = @db AND TABLE_NAME = 'categories' AND COLUMN_NAME = 'search_only_on_match');

SET @sql := IF(@had_flag > 0, 'SELECT 1',
    'ALTER TABLE categories ADD COLUMN search_only_on_match TINYINT(1) NOT NULL DEFAULT 0');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @sql := IF(@had_flag > 0, 'SELECT 1',
    'UPDATE categories SET search_only_on_match = 1 WHERE slug IN (''religion'', ''health-beauty'')');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- Інтенти (згенеровано: php tools/eli-intents.php sql)

-- EN-тексти запасного режиму «нічого впевненого» (app/translations.php).
ON DUPLICATE KEY UPDATE translated_text = VALUES(translated_text), source = 'manual';
